const r = $json.relatorio || {};
const brl = v => 'R$ ' + Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const MES=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const mesLabel = ym => { const p=String(ym||'').split('-'); return p.length===2 ? `${MES[+p[1]-1]} ${p[0]}` : ym; };
const CAT = {'Groceries':'Mercado','Food delivery':'Delivery','Eating out':'Restaurante','Food and drinks':'Alimentação','Housing':'Moradia','Digital services':'Serviços digitais','Shopping':'Compras','Clothing':'Roupas','Pharmacy':'Farmácia','Healthcare':'Saúde','Gas stations':'Posto de gasolina','Transfers':'Transferências','Transfer - PIX':'PIX','Insurance':'Seguro','Services':'Serviços','Gaming':'Games','Taxes':'Impostos','Electricity':'Energia','Internet':'Internet','Telecommunications':'Telecom','Pet supplies and vet':'Pet e veterinário','Loans and financing':'Empréstimos e financiamentos','Tickets':'Ingressos','Taxi and ride-hailing':'Táxi e apps','Wellness':'Bem-estar'};
const tr = c => CAT[c] || c;
const L = [`👫 *Relatório do casal — ${r.periodo}*`, '', '*Despesa e receita (Matheus + Ariane)*'];
(r.meses||[]).forEach(m => L.push(`• ${mesLabel(m.mes)}: gasto ${brl(m.despesa)} · entrou ${brl(m.receita)}`));
L.push('', '*Maiores gastos (últimos 30 dias)*');
if (!(r.topcat||[]).length) L.push('• sem dados');
(r.topcat||[]).forEach(c => L.push(`• ${tr(c.categoria)}: ${brl(c.total)} (${c.qtd})`));
L.push('', `💳 Faturas em aberto (total): ${brl(r.faturas_total)}`);
L.push(`📈 Investido (carteira): ${brl(r.invest)}`);
return [{ json: { text: L.join('\n') } }];
